using UnityEngine;

namespace KnockbackRumble
{
    /// <summary>
    /// The game-show look for all menus: loads the art and fonts from Art/Resources/UI and
    /// provides drawing helpers (panels, buttons, pills, text with drop shadows, icons).
    /// Art is generated by Tools/make_ui_art.py. Every texture is grayscale-on-dark so
    /// buttons and pills can be tinted to any color.
    /// </summary>
    public static class UiSkin
    {
        public static readonly Color Yellow = new Color(1f, 0.79f, 0.16f);
        public static readonly Color Teal = new Color(0.18f, 0.77f, 0.71f);
        public static readonly Color Dark = new Color(0.36f, 0.33f, 0.50f);
        public static readonly Color Red = new Color(0.90f, 0.27f, 0.30f);
        public static readonly Color Green = new Color(0.18f, 0.80f, 0.44f);
        public static readonly Color PillDark = new Color(0.16f, 0.15f, 0.22f);
        public static readonly Color Ink = new Color32(20, 18, 28, 255);
        public static readonly Color Cream = new Color32(255, 244, 214, 255);
        public static readonly Color Muted = new Color32(190, 182, 210, 255);
        public static readonly Color LabelBlue = new Color32(127, 219, 218, 255);
        public static readonly Color Gold = new Color32(255, 201, 40, 255);

        public static Font Display;   // Lilita One: buttons, headings
        public static Font Body;      // Nunito Black: names, fields
        public static Font BodyBold;  // Nunito Bold: small print

        public static Texture2D Logo, TitleLobby, TitlePaused, Avatar, BotIcon, MicIcon, CrownIcon, Dot,
            SwitchOn, SwitchOff, Stripes, Vignette, Spotlight;

        static Texture2D white;
        static GUIStyle panel, card, cardEmpty, pill, button, field, text;
        static bool loaded;

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        static void ResetStatics() => loaded = false;

        /// <summary>Call at the top of OnGUI.</summary>
        public static void Ensure()
        {
            if (!loaded)
            {
                loaded = true;
                Display = Resources.Load<Font>("UI/Fonts/LilitaOne-Regular");
                Body = Resources.Load<Font>("UI/Fonts/Nunito-Black");
                BodyBold = Resources.Load<Font>("UI/Fonts/Nunito-Bold");

                Logo = Tex("logo"); TitleLobby = Tex("title_lobby"); TitlePaused = Tex("title_paused");
                Avatar = Tex("avatar"); BotIcon = Tex("bot"); MicIcon = Tex("mic"); CrownIcon = Tex("crown"); Dot = Tex("dot");
                SwitchOn = Tex("switch_on"); SwitchOff = Tex("switch_off");
                Stripes = Tex("stripes"); Vignette = Tex("vignette"); Spotlight = Tex("spotlight");
                white = Texture2D.whiteTexture;

                panel = Slice(Tex("panel"), 30);
                card = Slice(Tex("card"), 26);
                cardEmpty = Slice(Tex("card_empty"), 26);
                pill = Slice(Tex("pill"), 15);

                button = Slice(Tex("btn_normal"), 24);
                button.hover.background = Tex("btn_hover");
                button.active.background = Tex("btn_down");

                var fieldTex = Tex("field");
                var fieldFocus = Tex("field_focus");
                field = Slice(fieldTex, 20);
                field.hover.background = fieldTex;
                field.focused.background = fieldFocus;
                field.active.background = fieldFocus;
                field.onFocused.background = fieldFocus;
                field.font = Body;
                field.fontSize = 30;
                field.alignment = TextAnchor.MiddleLeft;
                field.padding = new RectOffset(22, 22, 4, 4);
                field.clipping = TextClipping.Clip;
                field.normal.textColor = field.hover.textColor = field.focused.textColor = field.active.textColor = Ink;

                text = new GUIStyle { clipping = TextClipping.Clip, wordWrap = false, richText = false };
            }
            GUI.skin.settings.cursorColor = Ink;
            GUI.skin.settings.selectionColor = new Color(1f, 0.79f, 0.16f, 0.6f);
        }

        static Texture2D Tex(string name) => Resources.Load<Texture2D>("UI/" + name);

        static GUIStyle Slice(Texture2D tex, int border) => new GUIStyle
        {
            normal = { background = tex },
            border = new RectOffset(border, border, border, border),
        };

        static bool Repaint => Event.current.type == EventType.Repaint;

        // ---------- Shapes ----------

        static void Draw(GUIStyle style, Rect r, Color tint)
        {
            if (!Repaint || style == null) return;
            var old = GUI.backgroundColor;
            GUI.backgroundColor = tint;
            style.Draw(r, false, false, false, false);
            GUI.backgroundColor = old;
        }

        public static void Panel(Rect r) => Draw(panel, r, Color.white);
        public static void Card(Rect r) => Draw(card, r, Color.white);
        public static void CardEmpty(Rect r) => Draw(cardEmpty, r, Color.white);
        public static void Pill(Rect r, Color tint) => Draw(pill, r, tint);

        public static void Fill(Rect r, Color color)
        {
            if (!Repaint) return;
            var old = GUI.color;
            GUI.color = color;
            GUI.DrawTexture(r, white);
            GUI.color = old;
        }

        public static void Image(Rect r, Texture2D tex, Color tint)
        {
            if (!Repaint || tex == null) return;
            var old = GUI.color;
            GUI.color = tint;
            GUI.DrawTexture(r, tex, ScaleMode.StretchToFill, true);
            GUI.color = old;
        }

        public static void Image(Rect r, Texture2D tex) => Image(r, tex, Color.white);

        /// <summary>Height of a texture drawn at the given width (keeps its shape).</summary>
        public static float HeightFor(Texture2D tex, float width) => tex == null ? 0f : width * tex.height / tex.width;

        public static void StripeBand(Rect r)
        {
            if (!Repaint || Stripes == null) return;
            GUI.DrawTextureWithTexCoords(r, Stripes, new Rect(0f, 0f, r.width / 64f, r.height / 64f));
        }

        /// <summary>Dim the live course behind the menus, add a vignette, spotlights and hazard stripes.</summary>
        public static void StageBackground(float W, float H)
        {
            Fill(new Rect(0f, 0f, W, H), new Color(0.05f, 0.03f, 0.09f, 0.35f));
            Image(new Rect(0f, 0f, W, H), Vignette);
            Image(new Rect(W / 2f - 760f, -40f, 300f, 640f), Spotlight, new Color(1f, 1f, 1f, 0.8f));
            Image(new Rect(W / 2f + 460f, -40f, 300f, 640f), Spotlight, new Color(1f, 1f, 1f, 0.8f));
            StripeBand(new Rect(0f, 0f, W, 18f));
            StripeBand(new Rect(0f, H - 18f, W, 18f));
        }

        // ---------- Text ----------

        public static void Text(Rect r, string s, Font font, int size, Color color,
            TextAnchor align = TextAnchor.MiddleLeft, bool shadow = true)
        {
            text.font = font;
            text.fontSize = size;
            text.alignment = align;
            if (shadow)
            {
                text.normal.textColor = new Color(0f, 0f, 0f, 0.65f * color.a);
                GUI.Label(new Rect(r.x + 2f, r.y + 3f, r.width, r.height), s, text);
            }
            text.normal.textColor = color;
            GUI.Label(r, s, text);
        }

        public static void Heading(Rect r, string s, int size, Color color, TextAnchor align = TextAnchor.MiddleLeft) =>
            Text(r, s, Display, size, color, align);

        // ---------- Controls ----------

        static bool DarkText(Color tint) => tint == Yellow || tint == Teal || tint == Green;

        /// <summary>A chunky tinted button. sub is an optional second line.</summary>
        public static bool Button(Rect r, string label, Color tint, string sub = null, int size = 34, bool enabled = true)
        {
            bool wasEnabled = GUI.enabled;
            GUI.enabled = wasEnabled && enabled;
            var oldBg = GUI.backgroundColor;
            GUI.backgroundColor = tint;
            bool clicked = GUI.Button(r, GUIContent.none, button);
            GUI.backgroundColor = oldBg;

            bool dark = DarkText(tint);
            Color col = dark ? Ink : Cream;
            if (sub != null)
            {
                Text(new Rect(r.x, r.y + 8f, r.width, r.height * 0.5f), label, Display, size, col, TextAnchor.MiddleCenter, !dark);
                Text(new Rect(r.x, r.y + r.height * 0.5f, r.width, r.height * 0.32f), sub, BodyBold, 20,
                    new Color(col.r, col.g, col.b, 0.8f), TextAnchor.MiddleCenter, false);
            }
            else
            {
                Text(new Rect(r.x, r.y - 2f, r.width, r.height - 6f), label, Display, size, col, TextAnchor.MiddleCenter, !dark);
            }
            GUI.enabled = wasEnabled;
            return clicked;
        }

        public static string TextField(Rect r, string value, int maxLength, string controlName)
        {
            GUI.SetNextControlName(controlName);
            return GUI.TextField(r, value ?? "", maxLength, field);
        }

        /// <summary>An on/off switch; the whole row is clickable.</summary>
        public static bool Switch(Rect clickArea, Rect knob, bool on)
        {
            if (GUI.Button(clickArea, GUIContent.none, GUIStyle.none)) on = !on;
            Image(knob, on ? SwitchOn : SwitchOff);
            return on;
        }

        /// <summary>A small rounded label like HOST / YOU / TALKING, optionally with an icon. Returns its width.</summary>
        public static float Badge(float x, float y, string label, Color tint, Texture2D icon = null, float height = 34f)
        {
            float textWidth = label.Length * 12.5f + 24f;
            float w = textWidth + (icon != null ? 30f : 0f);
            Pill(new Rect(x, y, w, height), tint);
            float tx = x;
            if (icon != null)
            {
                Image(new Rect(x + 10f, y + (height - 22f) / 2f, 22f, 22f), icon, Ink);
                tx += 26f;
            }
            Text(new Rect(tx, y, w - (tx - x), height), label, Display, 20, Ink, TextAnchor.MiddleCenter, false);
            return w;
        }
    }
}
